from pathlib import Path
import json,hashlib,re
R=Path(__file__).resolve().parents[2]
record=R/'kb/records/cinema-deep-review-2026-10-30.json'
manifest=json.loads((R/'kb/research/culture/cinema-series/manifest.json').read_text())
def revise(slug, replacements=(), delete_starts=(), reason=''):
    p=R/next(a['source'] for a in manifest['articles'] if a['slug']==slug)
    d=json.loads(record.read_text()); assert d['active_article'] is None
    d['active_article']=slug;record.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
    old=p.read_text();new=old
    for a,b in replacements:
        assert new.count(a)==1,(slug,a[:100],new.count(a));new=new.replace(a,b,1)
    for start in delete_starts:
        parts=new.split('\n\n'); matches=[i for i,t in enumerate(parts) if t.startswith(start)]
        assert len(matches)==1,(slug,start,matches)
        parts.pop(matches[0]);new='\n\n'.join(parts)
    assert new!=old,slug
    p.write_text(new)
    d['changes'].append({'slug':slug,'reason':reason,'before_sha256':hashlib.sha256(old.encode()).hexdigest(),'after_sha256':hashlib.sha256(new.encode()).hexdigest(),'words_removed_net':len(old.split())-len(new.split()),'review':'pending independent integrated review'})
    d['active_article']=None;record.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
    print(slug, len(old.split())-len(new.split()),'words trimmed')

